// A missing scan root must yield an empty result without crashing.
{ // L18: real /dev char device presented under a hidraw name
    const std::string link_root = tmp_path("rawaccel_hidraw_link");
    std::filesystem::remove_all(link_root);
    std::filesystem::create_directories(link_root);
    std::error_code lfec;
    std::filesystem::create_symlink("/dev/zero", link_root + "/hidraw7", lfec);
    if (!lfec) {
        auto leaked = discover_logitech_hidraw_devices(link_root.c_str());
        EXPECT(leaked.empty());
    }
    std::filesystem::remove_all(link_root);
}
